import itertools

# Define the graph
edges = [
    # Clique on {0,1,2,3}
    (0,1), (0,2), (0,3), (1,2), (1,3), (2,3),
    # Clique on {4,5,6,7}
    (4,5), (4,6), (4,7), (5,6), (5,7), (6,7),
    # One edge connecting the cliques
    (0,4)
]

# Build adjacency set
n = 8
adj = [set() for _ in range(n)]
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check independence number
def max_independent_set_size(adj):
    n = len(adj)
    max_size = 0
    # Check all subsets
    for r in range(1, n+1):
        for subset in itertools.combinations(range(n), r):
            # Check if independent
            is_independent = True
            for i in range(r):
                for j in range(i+1, r):
                    if subset[j] in adj[subset[i]]:
                        is_independent = False
                        break
                if not is_independent:
                    break
            if is_independent:
                max_size = max(max_size, r)
    return max_size

alpha = max_independent_set_size(adj)
print(f"Independence number: {alpha}")

# Check vertex connectivity using Menger's theorem / networkx style
# Compute minimum vertex cut
# We can use brute force: try removing k vertices and check connectivity

def is_connected(adj, removed=set()):
    n = len(adj)
    start = None
    for i in range(n):
        if i not in removed:
            start = i
            break
    if start is None:
        return False
    visited = set()
    stack = [start]
    while stack:
        u = stack.pop()
        if u in visited:
            continue
        visited.add(u)
        for v in adj[u]:
            if v not in removed and v not in visited:
                stack.append(v)
    # Check all non-removed are visited
    for i in range(n):
        if i not in removed and i not in visited:
            return False
    return True

# Check connectivity
print(f"Connected: {is_connected(adj)}")

# Check vertex connectivity
vertex_conn = 0
for k in range(1, n):
    found_cut = False
    for removed in itertools.combinations(range(n), k):
        if not is_connected(adj, set(removed)):
            found_cut = True
            break
    if found_cut:
        vertex_conn = k
        break
    else:
        # If no cut of size k, then connectivity > k
        vertex_conn = k + 1

print(f"Vertex connectivity: {vertex_conn}")

# Also verify no independent set of size 3
print(f"Alpha <= 2: {alpha <= 2}")
print(f"Vertex connectivity >= 1: {vertex_conn >= 1}")
